import org.w3c.dom.Element;
import org.w3c.dom.NamedNodeMap;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.util.Collection;
import java.util.Collections;

public class StateListDetector extends ResourceXmlDetector {

    public static final Issue ISSUE = Issue.create(
            "StateListReachable",
            "Unreachable state in a `<selector>`",
            "In a selector, only the last child in the state list should omit a state qualifier. " +
            "If not, all subsequent items in the list will be ignored since the given item will match all.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(StateListDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(SdkConstants.TAG_SELECTOR);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        NodeList children = element.getChildNodes();
        int count = children.getLength();
        Element defaultItem = null;
        int defaultIndex = -1;

        // Find the last default item (item without state qualifiers)
        for (int i = 0; i < count; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element item = (Element) child;
                if (!hasStateQualifiers(item)) {
                    defaultItem = item;
                    defaultIndex = i;
                }
            }
        }

        // If a default item exists and is not the last element, report subsequent items as unreachable
        if (defaultItem != null) {
            for (int i = defaultIndex + 1; i < count; i++) {
                Node child = children.item(i);
                if (child.getNodeType() == Node.ELEMENT_NODE) {
                    context.report(ISSUE, context.getLocation(child),
                            "This item is unreachable because a previous item is a more general match than this one");
                }
            }
        }
    }

    private static boolean hasStateQualifiers(Element item) {
        NamedNodeMap attributes = item.getAttributes();
        if (attributes == null) {
            return false;
        }
        for (int i = 0, n = attributes.getLength(); i < n; i++) {
            Attr attr = (Attr) attributes.item(i);
            String name = attr.getLocalName();
            if (name == null) {
                name = attr.getName();
            }
            if (name.startsWith("android:")) {
                name = name.substring(8);
            }
            if (name.startsWith("state_")) {
                return true;
            }
        }
        return false;
    }
}
